<div class="heading"><div><h1><?=htmlspecialchars($title)?></h1><p class="muted">Gestión y consulta de registros.</p></div><?php if(in_array(Auth::user()['rol'],['administrador','recepcion'],true)):?><a class="btn" href="<?=BASE_URL.'/'.$controller?>/form">+ Nuevo</a><?php endif;?></div><div class="table-wrap"><table><thead><tr><?php if($rows)foreach(array_keys($rows[0]) as $h):?><th><?=htmlspecialchars(str_replace('_',' ',$h))?></th><?php endforeach;?><th>Acciones</th></tr></thead><tbody><?php foreach($rows as $r):?><tr><?php foreach($r as $v):?><td><?=htmlspecialchars((string)$v)?></td><?php endforeach;?><td><a href="<?=BASE_URL.'/'.$controller?>/form?id=<?=$r[$pk]?>">Editar</a><?php if(Auth::user()['rol']==='administrador'):?> · <a class="danger confirm" href="<?=BASE_URL.'/'.$controller?>/delete?id=<?=$r[$pk]?>">Desactivar</a><?php endif;?></td></tr><?php endforeach;?></tbody></table></div>

